state.saveOutputCode:
async function(result,args,action,direction,frame,start,visual_status="key_pose_passed_sequence_pending",attempt=1){
const root="D:/work/image/qdao_original_roster_v14_hd/action-remake-20261001/characters/02_fire_talisman_boy";
const id=action+"-"+direction+"-"+String(frame).padStart(2,"0")+"-20261002"+(attempt>1?"-attempt"+attempt:"");
const match=result.output_hint.match(/as (C:\\[^\n]+?\.png) by default/);
if(!match)throw Error("No actual source path in tool output");
const nativeFile="work/"+(action==="hit"?"hit":"run-"+direction)+"/"+direction+"-"+String(frame).padStart(2,"0")+(attempt>1?"-attempt"+attempt:"")+"-native.png";
const record={schemaVersion:1,action,direction,frame,status:"generated_exported_sequence_pending",file:nativeFile,submittedAt:start,timezone:"America/New_York",tool:"image_gen.imagegen",route:"builtin",configSnapshot:load("hitRecord").configSnapshot,submittedParameters:{...args,model:null,quality:null},actualModel:null,actualQuality:null,unverifiedReason:"宿主管理，工具未开放model/quality选择器，返回未披露实际模型/质量；实际值未确认。",prompt:"prompts/"+id+".txt",references:args.referenced_image_paths.map(path=>({path,sha256:(load("refSha")||{})[path]||null,viewed:true})),evidence:{sourcePath:match[1],resultKeys:Object.keys(result),output_hint:result.output_hint},export:{file:"frames/"+action+"/"+direction+"/"+String(frame).padStart(2,"0")+".png"},visual_status};
if(args.prompt.startsWith("Use case: identity-preserve")&&args.referenced_image_paths[0].includes("/work/"))record.editTarget={file:args.referenced_image_paths[0],sourceRecord:(load("sourceRecordMap")||{})[args.referenced_image_paths[0]]||null,sourceSha256:(load("refSha")||{})[args.referenced_image_paths[0]]||null};
const recPath=root+"/records/"+id+".generation.json";
const out=await tools.exec_command({cmd:"@'\n"+JSON.stringify(record,null,2)+"\n'@ | Set-Content -LiteralPath '"+recPath+"' -Encoding utf8\n& '"+root+"/tools/hit_production_save.ps1' -RecordPath '"+recPath+"'",max_output_tokens:1000});
text(out.output);return record;
}
